```javascript
// Pseudo-code sketch
while (streaming) {
  let X = STFT(frame);
  W = updateWhitening(X);
  Y = ICA(X, W); // per-frequency or joint-diagonalized
  alignPermutations(Y);
  x_hat = iSTFT(Y);
}
